<template><div><div class="page-header-card mb-4"><h1 class="text-2xl font-bold text-[#1A1A1A]">合同订单关联</h1><p class="text-xs text-gray-500 mt-1">仅已确认有效关联会用于混合业务统计</p></div><div class="content-card p-4 mb-4 flex gap-3"><el-input v-model="form.contract_no" placeholder="合同号"/><el-input v-model="form.order_no" placeholder="订单编号"/><el-input v-model="form.note" placeholder="备注（可选）"/><el-button type="primary" @click="save">确认关联</el-button></div><div class="content-card p-4"><el-input v-model="keyword" placeholder="搜索合同号或订单编号" style="width:260px" clearable @keyup.enter="load"/><el-button class="ml-2" @click="load">查询</el-button><el-table :data="rows" v-loading="loading" class="mt-4"><el-table-column prop="source_contract_no" label="合同号" width="180"/><el-table-column prop="contract.contract_name" label="合同名称" min-width="200"/><el-table-column prop="source_order_no" label="订单编号" width="180"/><el-table-column prop="status" label="状态" width="100"><template #default="{row}"><span class="tag" :class="row.status==='confirmed'?'tag-green':'tag-orange'">{{ row.status==='confirmed'?'已确认':row.status==='invalid'?'无效':'草稿' }}</span></template></el-table-column><el-table-column prop="confirmed_by" label="确认人" width="120"/><el-table-column prop="note" label="备注" min-width="150"/></el-table></div></div></template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { contractOrderLinkApi, type ContractOrderLink } from '../api/contractOrderLinkApi';
const rows=ref<ContractOrderLink[]>([]); const loading=ref(false); const keyword=ref(''); const form=reactive({contract_no:'',order_no:'',note:''});
async function load(){loading.value=true;try{const res=await contractOrderLinkApi.list({page:1,pageSize:100,keyword:keyword.value});if(res.code===200)rows.value=res.data.list;}finally{loading.value=false;}}
async function save(){const res=await contractOrderLinkApi.save(form);if(res.code===200){ElMessage.success('关联已确认');form.contract_no='';form.order_no='';form.note='';load();}else ElMessage.error(res.msg);}
onMounted(load);
</script>
